import csv
import json

CATALOG_PATH = "/root/therapy_catalog.json"
BAG_SUPPLY_COST_PATH = "/root/bag_supply_cost.csv"
DELIVERY_PAYMENT_PATH = "/root/delivery_payment.csv"
PATIENT_OVERRIDES_PATH = "/root/patient_overrides.csv"
ANALYSIS_OUTPUT_PATH = "/root/infusion_batch_analysis.json"
SUMMARY_OUTPUT_PATH = "/root/infusion_batch_summary.md"

SEVEN_DAY = {"days_per_delivery": 7, "deliveries_per_year": 52}
FOURTEEN_DAY = {"days_per_delivery": 14, "deliveries_per_year": 26}
THRESHOLD_USD = 15000.0


def include_flag(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() == "true"
    return False


def normalized_label(value):
    return str(value).strip().lower()


def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def load_therapies(path):
    with open(path) as f:
        catalog = json.load(f)

    if isinstance(catalog, list):
        therapies = catalog
    else:
        therapies = []
        for service_line in catalog.get("service_lines", []):
            therapies.extend(service_line.get("therapies", []))

    return [therapy for therapy in therapies if include_flag(therapy.get("include_in_review"))]


def currency(value):
    return round(float(value), 2)


def build_delivery_payment_lookup(rows, in_scope_therapies):
    label_to_code = {}
    for therapy in in_scope_therapies:
        therapy_code = therapy["therapy_code"]
        labels = [therapy.get("therapy_name", "")]
        labels.extend(therapy.get("aliases") or [])
        for label in labels:
            label_to_code[normalized_label(label)] = therapy_code

    payment_by_code = {}
    duplicate_payment_rows = []
    for row in rows:
        therapy_code = label_to_code.get(normalized_label(row.get("therapy_label", "")))
        if not therapy_code:
            continue
        if therapy_code in payment_by_code:
            duplicate_payment_rows.append(therapy_code)
        payment_by_code[therapy_code] = float(row["payment_per_delivery_per_patient_usd"])

    return payment_by_code, duplicate_payment_rows


def build_patient_lookup(rows, in_scope_codes):
    winning_rows = {}
    for row in rows:
        therapy_code = row.get("therapy_code", "").strip()
        if therapy_code not in in_scope_codes:
            continue
        if row.get("status", "").strip().lower() != "approved":
            continue

        revision = int(row["revision"])
        current = winning_rows.get(therapy_code)
        if current is None or revision > current["revision"]:
            patient_count_raw = row.get("patient_count")
            if patient_count_raw is None or patient_count_raw == "":
                patient_count_raw = row.get("active_patients")
            winning_rows[therapy_code] = {
                "revision": revision,
                "active_patients": int(patient_count_raw),
            }

    return {code: row["active_patients"] for code, row in winning_rows.items()}


def build_bag_cost_lookup(rows):
    return {
        int(row["bag_size_ml"]): float(row["bag_supply_cost_usd"])
        for row in rows
    }


def model_values(therapy, active_patients, payment, bag_cost, model):
    days_per_delivery = model["days_per_delivery"]
    deliveries_per_year = model["deliveries_per_year"]
    drug_cost_per_1000_mg = float(therapy["drug_cost_per_1000_mg_usd"])
    dose_mg_per_day = float(therapy["dose_mg_per_day"])

    annual_drug_cost = (
        drug_cost_per_1000_mg
        * active_patients
        * dose_mg_per_day
        * days_per_delivery
        * deliveries_per_year
        / 1000
    )
    annual_supply_cost = bag_cost * active_patients * deliveries_per_year
    annual_revenue = payment * active_patients * deliveries_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost

    return {
        "annual_drug_cost": currency(annual_drug_cost),
        "annual_supply_cost": currency(annual_supply_cost),
        "annual_revenue": currency(annual_revenue),
        "annual_margin": currency(annual_margin),
    }


def main():
    therapies = load_therapies(CATALOG_PATH)
    in_scope_codes = {therapy["therapy_code"] for therapy in therapies}

    bag_rows = read_csv(BAG_SUPPLY_COST_PATH)
    payment_rows = read_csv(DELIVERY_PAYMENT_PATH)
    patient_rows = read_csv(PATIENT_OVERRIDES_PATH)

    payment_by_code, duplicate_payment_rows = build_delivery_payment_lookup(payment_rows, therapies)
    active_patients_by_code = build_patient_lookup(patient_rows, in_scope_codes)
    bag_cost_by_size = build_bag_cost_lookup(bag_rows)

    therapy_results = []
    for therapy in therapies:
        therapy_code = therapy["therapy_code"]
        bag_size_ml = int(therapy["bag_size_ml"])
        active_patients = active_patients_by_code[therapy_code]
        payment = payment_by_code[therapy_code]
        bag_cost = bag_cost_by_size[bag_size_ml]

        seven_day = model_values(therapy, active_patients, payment, bag_cost, SEVEN_DAY)
        fourteen_day = model_values(therapy, active_patients, payment, bag_cost, FOURTEEN_DAY)
        margin_difference = currency(fourteen_day["annual_margin"] - seven_day["annual_margin"])

        therapy_results.append({
            "therapy_code": therapy_code,
            "therapy_name": therapy["therapy_name"],
            "active_patients": active_patients,
            "bag_size_ml": bag_size_ml,
            "bag_supply_cost_usd": currency(bag_cost),
            "payment_per_delivery_per_patient_usd": currency(payment),
            "drug_cost_per_1000_mg_usd": currency(therapy["drug_cost_per_1000_mg_usd"]),
            "dose_mg_per_day": float(therapy["dose_mg_per_day"]),
            "annual_drug_cost_7_day_usd": seven_day["annual_drug_cost"],
            "annual_drug_cost_14_day_usd": fourteen_day["annual_drug_cost"],
            "annual_supply_cost_7_day_usd": seven_day["annual_supply_cost"],
            "annual_supply_cost_14_day_usd": fourteen_day["annual_supply_cost"],
            "annual_revenue_7_day_usd": seven_day["annual_revenue"],
            "annual_revenue_14_day_usd": fourteen_day["annual_revenue"],
            "annual_margin_7_day_usd": seven_day["annual_margin"],
            "annual_margin_14_day_usd": fourteen_day["annual_margin"],
            "annual_margin_difference_14_minus_7_usd": margin_difference,
        })

    therapy_results.sort(key=lambda item: item["therapy_code"])

    total_7 = currency(sum(item["annual_margin_7_day_usd"] for item in therapy_results))
    total_14 = currency(sum(item["annual_margin_14_day_usd"] for item in therapy_results))
    total_difference = currency(total_14 - total_7)
    absolute_difference = currency(abs(total_difference))
    decision = "move_to_14_day" if absolute_difference < THRESHOLD_USD else "keep_7_day"

    analysis = {
        "assumptions": {
            "seven_day_model": {
                "days_per_delivery": SEVEN_DAY["days_per_delivery"],
                "deliveries_per_year": SEVEN_DAY["deliveries_per_year"],
            },
            "fourteen_day_model": {
                "days_per_delivery": FOURTEEN_DAY["days_per_delivery"],
                "deliveries_per_year": FOURTEEN_DAY["deliveries_per_year"],
            },
            "supply_cost_rule": "Each delivery uses 1 bag per patient; supply cost is per delivery per patient.",
            "decision_threshold_usd": currency(THRESHOLD_USD),
            "duplicate_delivery_payment_therapy_codes_seen": sorted(set(duplicate_payment_rows)),
        },
        "therapies": therapy_results,
        "totals": {
            "total_annual_margin_7_day_usd": total_7,
            "total_annual_margin_14_day_usd": total_14,
            "total_annual_margin_difference_14_minus_7_usd": total_difference,
            "absolute_total_margin_difference_usd": absolute_difference,
        },
        "recommendation": {
            "decision": decision,
            "justification": f"The absolute total annual margin difference is ${absolute_difference:.2f}, compared with the ${THRESHOLD_USD:.2f} threshold.",
        },
    }

    with open(ANALYSIS_OUTPUT_PATH, "w") as f:
        json.dump(analysis, f, indent=2)
        f.write("\n")

    summary = "\n".join([
        "# Infusion Batch Analysis Summary",
        "",
        f"Total 7-day annual margin: ${total_7:.2f}",
        f"Total 14-day annual margin: ${total_14:.2f}",
        f"Absolute margin difference: ${absolute_difference:.2f}",
        f"Recommendation: {decision}",
        "",
    ])
    with open(SUMMARY_OUTPUT_PATH, "w") as f:
        f.write(summary)


if __name__ == "__main__":
    main()

